--==================#1 BACKUP EDS TABLE===================
DECLARE @sql NVARCHAR(MAX);
DECLARE @TGT_CNT [NUMERIC](15,0);
DECLARE @BKUP_CNT [NUMERIC](15,0);
DECLARE @PREV_PROCESS_DATE DATE;
DECLARE @backupName NVARCHAR(128);
DECLARE @SCD_FLAG [NUMERIC](15,0);
DECLARE @outputstring NVARCHAR(4000);
DECLARE @SUFFIX INT = 0;
DECLARE @BU_DATE CHAR(8);


----===========CHECK IF SCD TYPE 2==================================
SET @SCD_FLAG = (SELECT COUNT(*) FROM OM.OM_TASKS WHERE TABLE_NAME=@tableName AND DATA_LAYER=@DATA_LAYER AND TABLE_TYPE='SCD TYPE 2')
IF(@SCD_FLAG<1)
BEGIN
   DECLARE @errmsg NVARCHAR(2048) = 'Table is not SCD TYPE 2. Execution Terminated';
   THROW 50002, @errmsg, 1;  
END 
 
SET @PREV_PROCESS_DATE = (SELECT PREVIOUS_BUSINESS_DAY FROM EDS.DATE_DIM WHERE FULLDATE=@PROCESS_DATE)
SET @BU_DATE = CONVERT(CHAR(8), CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Singapore Standard Time' AS DATE), 112);
SET @backupName = @tableName+ '_' + @ticketNumber + '_BU_' + @BU_DATE;
 
IF EXISTS (
    SELECT 1
    FROM INFORMATION_SCHEMA.TABLES
    WHERE TABLE_NAME = @backupName AND TABLE_SCHEMA = 'D360'
)
BEGIN
    -- Find the highest suffix number
    SELECT TOP 1
        @SUFFIX = TRY_CAST(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1) AS INT)
    FROM INFORMATION_SCHEMA.TABLES
    WHERE
        TABLE_NAME LIKE @backupName + '_%'
        AND TABLE_SCHEMA = 'D360'
        AND ISNUMERIC(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1)) = 1
    ORDER BY CAST(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1) AS NUMERIC(15,0)) DESC;
 
    -- If no _1 exists, make _1. Otherwise, increment.
    SET @SUFFIX = ISNULL(@SUFFIX, 0) + 1;
    SET @backupName = @backupName + '_' + CAST(@SUFFIX AS VARCHAR);
END
 
SET @sql = '
CREATE TABLE D360.' + QUOTENAME(@backupName) + '
WITH
(
    DISTRIBUTION= ROUND_ROBIN, HEAP
)
AS
SELECT *
FROM EDS.' + @tableName + ';';
 
EXEC sp_executesql @sql;


---================#2 VALIDATION==================================---

DECLARE @SQLString NVARCHAR(MAX);  
DECLARE @ParmDefinition NVARCHAR(500);  
DECLARE @count_tgt NVARCHAR(500);
DECLARE @count_bkp NVARCHAR(500);

SET @SQLString = 'SELECT @count_tgt = count(1)   FROM EDS.'+@tableName ;  
SET @ParmDefinition = '@count_tgt [NUMERIC](15,0) OUTPUT';  
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_tgt=@count_tgt OUTPUT;  

set @outputstring = 'INSERT INTO OM.OM_CLEANUP_DTL SELECT '''+ @tablename +''',''Target table ' + @tablename + ' Record count: '+ @count_tgt + ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';

SET @SQLString = 'SELECT @count_bkp = count(1)   FROM D360.'+QUOTENAME(@backupName) ;  
SET @ParmDefinition = '@count_bkp [NUMERIC](15,0) OUTPUT';  
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_bkp=@count_bkp OUTPUT;  

set @outputstring = @outputstring + ' UNION ALL SELECT '''+ @tablename +''',''Backup table ' + QUOTENAME(@backupName) + ' Record count: ' + @count_bkp + ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';
--set @count_bkp=100
IF(@count_tgt<>@count_bkp)
BEGIN

   DECLARE @errmsg1 NVARCHAR(2048) = 'Record count between target table and backup table does not match';
   
   THROW 50001, @errmsg1, 1;  
END 


--===============#3 DELETE =====================================-

SET @SQLString = 'SELECT @count_tgt = count(1) FROM EDS.'+ @tableName +' WHERE REPLACE(' + @DATE_COLUMN + ',''-'','''') >= '+ REPLACE(@PROCESS_DATE,'-',''); 
SET @ParmDefinition = '@count_tgt [NUMERIC](15,0) OUTPUT'; 
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_tgt=@count_tgt OUTPUT;  
 
SET @SQLString = 'Delete FROM EDS.'+ @tableName +' WHERE REPLACE(' + @DATE_COLUMN + ',''-'','''') >= '+ REPLACE(@PROCESS_DATE,'-',''); 
EXECUTE sp_executesql @SQLString;  

set @outputstring = @outputstring + ' UNION ALL SELECT '''+ @tablename +''','''+ @tableName +' Deleted record count: '+ @count_tgt + ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';


--=============#5 UPDATE=============
SET @SQLString = 'SELECT @count_tgt = count(1) FROM EDS.'+ @tableName +' WHERE CONVERT(varchar(12), SCD_END_DATE, 112) >='+ REPLACE(@PREV_PROCESS_DATE,'-',''); 
SET @ParmDefinition = '@count_tgt [NUMERIC](15,0) OUTPUT'; 
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_tgt=@count_tgt OUTPUT;  
 
SET @SQLString = 'Update EDS.'+ @tableName +' SET SCD_END_DATE = ''9999-12-31'', ISLATEST =  1 WHERE CONVERT(varchar(12), SCD_END_DATE, 112) >='+ REPLACE(@PREV_PROCESS_DATE,'-',''); 
EXECUTE sp_executesql @SQLString;  

set @outputstring = @outputstring + ' UNION ALL SELECT '''+ @tablename +''','''+ @tableName +' Updated record count: '+ @count_tgt+ ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';





--==================#7 BACKUP OM TASK RUN TABLE===================

SET @BU_DATE = CONVERT(CHAR(8), CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Singapore Standard Time' AS DATE), 112);
SET @backupName = @omtableName+ '_' + @ticketNumber + '_BU_' + @BU_DATE;
 
IF EXISTS (
    SELECT 1
    FROM INFORMATION_SCHEMA.TABLES
    WHERE TABLE_NAME = @backupName AND TABLE_SCHEMA = 'D360'
)
BEGIN
    -- Find the highest suffix number
    SELECT TOP 1
        @SUFFIX = TRY_CAST(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1) AS INT)
    FROM INFORMATION_SCHEMA.TABLES
    WHERE
        TABLE_NAME LIKE @backupName + '_%'
        AND TABLE_SCHEMA = 'D360'
        AND ISNUMERIC(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1)) = 1
    ORDER BY CAST(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1) AS NUMERIC(15,0)) DESC;
 
    -- If no _1 exists, make _1. Otherwise, increment.
    SET @SUFFIX = ISNULL(@SUFFIX, 0) + 1;
    SET @backupName = @backupName + '_' + CAST(@SUFFIX AS VARCHAR);
END
 
SET @sql = '
CREATE TABLE D360.' + QUOTENAME(@backupName) + '
WITH
(
    DISTRIBUTION= ROUND_ROBIN, HEAP
)
AS
SELECT *
FROM OM.' + @omtableName + ';';
 
EXEC sp_executesql @sql;



---================#8 VALIDATION==================================---

SET @SQLString = 'SELECT @count_tgt = count(1)   FROM OM.'+@omtableName ;  
SET @ParmDefinition = '@count_tgt [NUMERIC](15,0) OUTPUT';  
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_tgt=@count_tgt OUTPUT;  

set @outputstring = @outputstring + ' UNION ALL SELECT '''+ @tablename +''',''Target table ' + @omtableName + ' Record count: '+ @count_tgt+ ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';

SET @SQLString = 'SELECT @count_bkp = count(1)   FROM D360.'+QUOTENAME(@backupName) ;  
SET @ParmDefinition = '@count_bkp [NUMERIC](15,0) OUTPUT';  
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_bkp=@count_bkp OUTPUT;  

set @outputstring = @outputstring + ' UNION ALL SELECT '''+ @tablename +''','' Backup table ' + QUOTENAME(@backupName) + ' Record count: ' + @count_bkp+ ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';
IF(@count_tgt<>@count_bkp)
BEGIN

   SET @errmsg1 = 'Record count between target table and backup table does not match';
   
   THROW 50001, @errmsg1, 1;  
END 


--===============#9 UPDATE =====================================-
SET @SQLString = 'SELECT @count_tgt = count(1) FROM OM.'+ @omtableName +' WHERE (TASK_NAME LIKE ''%_'+ @tableName +'%'' OR TASK_NAME LIKE ''%_'+ @stgtableName +'%'') AND CONVERT(varchar(12), PROCESS_DATE, 112) >='+ REPLACE(@PROCESS_DATE,'-','') + '  AND DATA_LAYER LIKE ''%'+ @DATA_LAYER +'%''';
SET @ParmDefinition = '@count_tgt [NUMERIC](15,0) OUTPUT'; 
EXECUTE sp_executesql @SQLString, @ParmDefinition,  @count_tgt=@count_tgt OUTPUT;  

 
SET @SQLString = 'UPDATE OM.'+ @omtableName +' SET STATUS_ID = (SELECT STATUS_ID FROM OM.OM_STATUS WHERE STATUS=''FOR RE-EXECUTION'') WHERE (TASK_NAME LIKE ''%_'+ @tableName +'%'' OR TASK_NAME LIKE ''%_'+ @stgtableName +'%'') AND CONVERT(varchar(12), PROCESS_DATE, 112) >='+ REPLACE(@PROCESS_DATE,'-','') + '  AND DATA_LAYER LIKE ''%'+ @DATA_LAYER +'%''';

EXECUTE sp_executesql @SQLString;  

set @outputstring = @outputstring + ' UNION ALL SELECT '''+ @tablename +''',''' + @omtableName +' Updated record count: '+ @count_tgt+ ''','''+ @DATA_LAYER + ''','''+ cast(@PROCESS_DATE as NVARCHAR(10)) + ''',CAST(SYSDATETIMEOFFSET() AT TIME ZONE ''Singapore Standard Time'' AS datetime)';


EXECUTE sp_executesql @outputstring;
